#include "../src/planner/Dijkstra.h"
#include <cassert>
int main(){ds::Graph g;for(auto id:{"a","b","c","d"}){ds::Place p;p.id=id;g.add_place(p);}auto add=[&](const char* id,const char* u,const char* v,const char* way,double d){ds::Road r;r.id=id;r.u=u;r.v=v;r.osm_way=way;r.directed=true;r.distance_km=d;r.base_time_min=d;g.add_road(r);};add("ab","a","b","1",1);add("bc","b","c","2",1);add("ad","a","d","3",2);add("db","d","b","4",2);ds::DynArray<ds::Graph::Turn> rules;rules.push_back({"1","2",false});g.turns.insert("b",rules);planner::Dijkstra::Options o;o.mode=planner::Mode::Shortest;auto r=planner::Dijkstra::find_path(g,0,2,o);assert(r.found&&r.total_distance_km==5);assert(!planner::Dijkstra::find_path(g,2,0,o).found);rules.clear();rules.push_back({"1","99",true});g.turns.insert_or_assign("b",rules);assert(planner::Dijkstra::find_path(g,0,2,o).total_distance_km==5);}
